// source: cv.go
/*
Package cv is the CV-builder domain: the structured CV Document, its sanitizer,
seeding from the extracted résumé, and PDF rendering behind a Renderer interface.
*/

/**
 * DefaultMaxBullets is the per-experience / per-project bullet ceiling when
 * CV_MAX_BULLETS is unset. Writers must refuse growth past MaxBullets rather
 * than let Sanitize drop trailing content silently.
 */
export const DefaultMaxBullets = 20;
/**
 * Document is the typed, sanitized CV. Every field is optional; sections the user has
 * not filled in are left empty rather than invented, and Sanitize drops empty entries.
 */
export interface Document {
  margins: Margins;
  /**
   * No omitempty: it does nothing on a struct (encoding/json only omits false, 0, nil, and
   * empty strings/slices/maps), so the tag would promise clients an absence they never see
   * while making the generated TypeScript optional for no reason.
   */
  style: Style;
  header: Header;
  summary?: string;
  experience?: ExperienceItem[];
  education?: EducationItem[];
  skills?: SkillGroup[];
  languages?: Language[];
  projects?: Project[];
  certifications?: Certification[];
}
/**
 * Margins is the CV's per-side page margin in inches, applied identically to the HTML
 * preview and the Typst-rendered PDF. Sanitize clamps each side and defaults an unset
 * (zero) side to defaultMargin.
 */
export interface Margins {
  top: number /* float64 */;
  right: number /* float64 */;
  bottom: number /* float64 */;
  left: number /* float64 */;
}
/**
 * Style is the CV's typography: the typeface, the base type size in points, and the line
 * height as a leading multiple of the em. It is part of the document, so it persists with
 * the CV, is copied when the CV is tailored, and is not clobbered by field-level patches.
 * A zero value means "whatever the active template uses" and Sanitize KEEPS IT ZERO. This is
 * the opposite of Margins, which resolves an unset side to a concrete 0.5in, and the
 * difference is deliberate on both counts:
 *   - Every CV written before this type existed has no style block, so it renders exactly as
 *     it did. There is nothing to migrate.
 *   - A template stays a whole design choice. Switching to a template with looser leading
 *     actually loosens the leading, because that value was never frozen into the document.
 * Resolving defaults here — the natural thing to do by analogy with clampMargin — would
 * silently bake the current template's typography into every document on its next save.
 * FontFamily is a registry id (see fonts.go), never a renderer's own face name: the renderer
 * resolves it on its own copy of the document at render time.
 */
export interface Style {
  font_family?: string;
  font_size?: number /* float64 */; // points
  line_height?: number /* float64 */; // em of leading
}
/**
 * Header is the top-of-CV contact block. The tagline under the name is Document.Summary
 * (there is no separate headline field — one "summary" term across the CV).
 */
export interface Header {
  full_name?: string;
  email?: string;
  phone?: string;
  location?: string;
  links?: string[];
}
/**
 * Experience is one work-history entry. Start/End are a structured perioddate.PeriodDate
 * (year, optional month) — the same shared type experience.Employment and
 * resumeextract.Experience use. Rendering to PDF formats this back to display text
 * (see renderer.go); no template deals with the structured value directly.
 */
export interface ExperienceItem {
  role?: string;
  company?: string;
  location?: string;
  start?: { year: number; month?: number };
  end?: { year: number; month?: number };
  current?: boolean;
  /**
   * Summary is the one-line company/role context printed under the role header, before
   * the bullets. Stack is the per-role technology line printed after the bullets.
   */
  summary?: string;
  bullets?: string[];
  stack?: string[];
}
/**
 * Education is one education entry. Start/End are the same structured perioddate.PeriodDate.
 */
export interface EducationItem {
  institution?: string;
  degree?: string;
  field?: string;
  start?: { year: number; month?: number };
  end?: { year: number; month?: number };
}
/**
 * SkillGroup is a named cluster of skills (e.g. "Languages" → Go, Python). A group with
 * no items and no name is dropped.
 */
export interface SkillGroup {
  group?: string;
  items?: string[];
}
/**
 * Language is one spoken/written language and its proficiency level.
 */
export interface Language {
  name?: string;
  level?: string;
}
/**
 * Project is one portfolio/side-project entry.
 */
export interface Project {
  name?: string;
  link?: string;
  bullets?: string[];
}
/**
 * Certification is one certification/credential. Year is the same structured
 * perioddate.PeriodDate.
 */
export interface Certification {
  name?: string;
  issuer?: string;
  year?: { year: number; month?: number };
}

/**
 * RevisionView is one entry in the history feed.
 * It deliberately does NOT carry the operations. The feed needs to say what changed and
 * where, not to reproduce it: the addresses are enough to underline the right lines in the
 * preview, while the inverses hold the candidate's own earlier text and have no business
 * leaving the server for a list view.
 */
export interface RevisionView {
  id: string;
  /**
   * Actor is who made the change: the candidate, the agent, or the system.
   */
  actor: string;
  /**
   * Origin is the entry point it arrived through — the editor, the template picker, the
   * tailoring agent, the CLI, an import.
   */
  origin: string;
  /**
   * BatchID groups the edits of one agent turn, so the feed can offer to undo the run as
   * a whole. Empty for a change that stands alone.
   */
  batch_id?: string;
  /**
   * Title describes the change in the application's own words. It is generated from the
   * operations on the server and never written by a model.
   */
  title: string;
  /**
   * Note is the agent's own reason for the edit, when it gave one. It is the model's text
   * and must be rendered as the agent's words, attributed — never as the entry's own
   * description.
   */
  note?: string;
  /**
   * Paths are the places this revision touched, e.g. `experience[2].bullets[1]`. The
   * preview underlines the nodes they address.
   */
  paths: string[];
  /**
   * Reverted says the change has already been undone, which is what greys out its control
   * rather than removing the entry: the log is never rewritten.
   */
  reverted: boolean;
  /**
   * Undoable says the entry has something to reverse. A milestone — "this CV was created"
   * — has not: undoing it would mean deleting the CV, which is a different action with its
   * own button. Stated rather than inferred from an empty path list, because "changed
   * nothing addressable" and "cannot be undone" are different facts.
   */
  undoable: boolean;
  /**
   * RevertsID names the revision this one undid, when it is itself an undo.
   */
  reverts_id?: string;
  created_at: string;
}

/**
 * Display is a captured form shaped for a candidate to read rather than for a
 * machine to submit. It is the near-inverse of what the store keeps: the store holds
 * the platform's identifiers and option values because they exist to be handed back,
 * and a reader wants none of that — only the question and one word about the answer.
 */
export interface Display {
  /**
   * Provider is the platform the form was read from, so a reader can say where the
   * answer came from.
   */
  provider: string;
  /**
   * Basics are the controls every application demands — name, contact details, CV —
   * listed once instead of one entry each. Stated rather than dropped, because a
   * form that does NOT want a CV is worth knowing too.
   */
  basics: string[];
  /**
   * Questions are the employer's own, in the order the form presents them.
   */
  questions: Question[];
}
/**
 * Question is one thing the employer will ask.
 */
export interface Question {
  /**
   * Text is the question as the employer wrote it, unedited.
   */
  text: string;
  /**
   * Required is whether the platform refuses the application without an answer.
   */
  required: boolean;
  /**
   * Answer names the kind of answer expected, empty where naming it would add
   * nothing (a one-line answer is the default expectation) or where the capture
   * could not normalize the control's kind.
   */
  answer?: string;
}

/**
 * Answers is the candidate's stated screening answers. Every field is independently
 * optional: a nil pointer (or a nil/empty slice for AuthorizedCountries) means the
 * candidate has not stated that fact, never a guessed default.
 */
export interface Answers {
  authorized_countries?: string[];
  visa_sponsorship_needed?: boolean;
  desired_salary_amount?: number /* int */;
  desired_salary_currency?: string;
  desired_salary_period?: string;
  notice_period_days?: number /* int */;
  willing_to_relocate?: boolean;
  age_18_or_older?: boolean;
  /**
   * PrivacyConsent is the candidate's standing agreement to the privacy / personal-data
   * processing terms an employer's form makes a condition of applying. Not a fact about
   * the candidate like the fields above but a permission they grant: nil until they turn
   * it on, and false is a refusal the resolver honours by asking them each time.
   */
  privacy_consent?: boolean;
}

/**
 * Responses is one candidate's survey record. Every field is independently optional: a nil
 * pointer means the candidate has not stated that fact, never a guessed default and never
 * a zero standing in for silence.
 */
export interface Responses {
  job_search_stage?: string;
  biggest_challenge?: string;
  /**
   * BiggestChallengeNote is free text, and only vocab.JobChallengeOther admits it. A note
   * beside a coded challenge could contradict it, and nothing downstream would know which
   * to believe.
   */
  biggest_challenge_note?: string;
  current_income_amount?: number /* int */;
  current_income_currency?: string;
  current_income_period?: string;
}

/**
 * CandidateCard is one candidate as the public catalogue shows them.
 */
export interface CandidateCard {
  /**
   * Seniority and Category describe the candidate as a whole: what their current (or
   * most recent) role resolves to. This is the card's heading, built rather than
   * quoted — see PrimaryTitle.
   */
  seniority?: string;
  category?: string;
  /**
   * TotalYears is the CV's own figure. A number cannot carry a name.
   */
  total_years?: number /* int */;
  /**
   * Skills are skilltag canonicals. A token the dictionary does not resolve emits
   * nothing, which is exactly the whitelisting this card needs — see skilltag's
   * "never guess" rule.
   */
  skills: string[];
  /**
   * Roles is the work history with everything nameable removed: no employer, no
   * location, no prose. What remains is the shape of a career, which is what a
   * recruiter reads a history for anyway.
   */
  roles: CandidateRole[];
  /**
   * Education carries only what internal/dict/edulevel resolves from each entry's
   * degree text, plus its year — never the institution or field of study. An entry
   * whose degree resolves to nothing is dropped rather than kept under an empty
   * label: a work-history gap reads worse than absence, but a candidate's set of
   * degrees carries no such expectation of completeness.
   */
  education?: EducationEntry[];
  /**
   * Certifications are internal/dict/certification canonicals. A name the dictionary
   * does not resolve emits nothing, the same whitelisting Skills gets from skilltag.
   */
  certifications?: string[];
}
/**
 * EducationEntry is one education item, reduced to what a dictionary can vouch for:
 * the degree's level and the year, never the institution.
 */
export interface EducationEntry {
  level?: string;
  year?: { year: number; month?: number };
}
/**
 * CandidateRole is one position: what it was, when, and what it was built with.
 */
export interface CandidateRole {
  /**
   * Title is the candidate's own words, verbatim — the card's ONE exception to the
   * dictionary-only rule, argued in this file's header comment. Seniority and Category
   * remain beside it as the fallback for a role whose title is absent, and as the
   * values every filter reads: the raw string is for a human to read, never to match on.
   */
  title?: string;
  seniority?: string;
  category?: string;
  start?: { year: number; month?: number };
  end?: { year: number; month?: number };
  current?: boolean;
  stack?: string[];
}
/**
 * CatalogueMember is one entry in the public catalogue: the dictionary-checked card, plus the
 * facts that live in columns rather than in the CV.
 * Every field here survives the same rule ProjectCard enforces. Cities are the NORMALISED
 * extraction (users.resume_cities), not the free-text location inside the CV, which
 * carries values like "Austria, Klagenfurt 9020"; the timezone is an IANA zone;
 * specializations are drawn from vocab.CategoryValues by the profile form. None of the
 * three can carry a sentence.
 * Specializations are NOT a duplicate of Card.Category, and the difference is the useful
 * part. Category is derived from what the candidate has DONE — the title of their most
 * recent role, through classify. Specializations are what they SAY they want, ticked from
 * the same closed vocabulary on their own profile. A backend engineer whose profile says
 * `ml_ai` is somebody a recruiter wants to find, and the two fields disagreeing is the
 * only way that shows.
 */
export interface CatalogueMember {
  handle: string;
  card: CandidateCard;
  /**
   * Timezone is the IANA zone; TimezoneRegion is the part before the slash. The region
   * is what a recruiter asking "can we overlap for a call" actually means — there are
   * dozens of zones per continent — so it is what the filter reads.
   */
  timezone?: string;
  timezone_region?: string;
  cities: string[];
  specializations: string[];
  /**
   * UpdatedAt is when the structured extract was written, which is the freshest thing
   * the catalogue knows about a member. It orders the list.
   */
  updated_at: string;
  /**
   * HasPhoto says only whether GET /talent/{handle}/photo has something to serve —
   * never the object key, and never the image itself. It survives the card's own
   * dictionary-only rule because a boolean carries no name: the alternative was every
   * list card firing that request and reading the 404 GetPhoto already gives a member
   * with none, which is correct but a wasted round trip for what is, in practice, most
   * of the catalogue.
   */
  has_photo: boolean;
}

